.cs-comment-body .mw-editsection{display:none}#go-top{display:none;position:fixed;bottom:30px;right:30px;background:#3366cc;color:#fff;padding:8px 12px;border-radius:4px;text-decoration:none;font-size:0.9em;z-index:1000}#go-top:hover{background:#2a55a5}li#ca-talk{display:none;!important}.full,.reply{width:100% !important;max-width:100% !important;box-sizing:border-box}.f-message,.r-message{width:100% !important;max-width:100% !important;box-sizing:border-box}.c-form-message,textarea#comment{width:100% !important;max-width:100% !important;box-sizing:border-box}#ca-viewsource{display:none !important}.tb_red{color:#ff0000}.tb_red_bold{color:#ff0000;font-weight:bold}.tb_blue{color:#0000ff}.tb_blue_bold{color:#0000ff;font-weight:bold}details{border:.05rem solid #448aff;line-height:1.6;border-radius:.2rem;box-shadow:var(--md-shadow-z1);color:var(--md-admonition-fg-color);display:flow-root !important;;margin:1.0em 0;padding:0 0.6rem;page-break-inside:avoid }summary{border-color:#64dd17;background-color:#64dd171a;border:none;font-weight:700;margin:0 -.6rem;padding-bottom:.4rem;padding-top:.4rem;position:relative }toc,.mw-warning,.toccolours{border:1px solid #64dd17;background-color:white;margin-bottom:0.5em;padding:5px;font-size:95% }